export function busRoutes(routes            , source        , target        )         {
if(source===target)return 0;const byStop=new Map                 ();routes.forEach((route,i)=>route.forEach(s=>{if(!byStop.has(s))byStop.set(s,[]);byStop.get(s) .push(i);}));let q=[source],count=0;const stops=new Set(q),buses=new Set        ();while(q.length){const next         =[];count++;for(const stop of q)for(const i of byStop.get(stop)??[]){if(buses.has(i))continue;buses.add(i);for(const s of routes[i]){if(s===target)return count;if(!stops.has(s)){stops.add(s);next.push(s);}}}q=next;}return -1;
}

